import { useState } from 'react';
import { useNavigate, Link, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import AuthHeader from '../components/AuthHeader';
import styles from './Auth.module.css';

const loginHighlights = [
  {
    icon: 'GR',
    title: 'Group dashboards',
    text: 'Jump back into active community groups with the latest balances and activity.',
  },
  {
    icon: 'RP',
    title: 'Recent activity',
    text: 'Review repayments, contributions, and payouts without a cluttered layout.',
  },
  {
    icon: 'IV',
    title: 'Investment views',
    text: 'Track pooled funds and returns from the same clean Finbric workspace.',
  },
];

function AuthHero() {
  return (
    <aside className={styles.hero}>
      <div className={styles.brandCompact}>
        <span className={styles.brandMark}>F</span>
        <div>
          <p className={styles.brandName}>Finbric</p>
          <p className={styles.brandTagline}>Community finance platform</p>
        </div>
      </div>
      <div className={styles.heroSwitchRow} aria-hidden="true">
        <span className={`${styles.heroSwitch} ${styles.heroSwitchActive}`}>Groups</span>
        <span className={styles.heroSwitch}>Loans</span>
        <span className={styles.heroSwitch}>Reports</span>
      </div>
      <span className={styles.eyebrow}>Welcome back</span>
      <h1 className={styles.heroTitle}>Sign in to your community dashboard.</h1>
      <p className={styles.heroText}>
        Access your groups, loans, investments, and member balances from the new Finbric screen.
      </p>
      <div className={styles.heroCard}>
        {loginHighlights.map((item) => (
          <div key={item.title} className={styles.featureItem}>
            <span className={`${styles.featureIcon} ${styles.featureIconPlan}`}>{item.icon}</span>
            <div>
              <p className={styles.featureTitle}>{item.title}</p>
              <p className={styles.featureText}>{item.text}</p>
            </div>
          </div>
        ))}
      </div>
    </aside>
  );
}

export default function Login() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const [form, setForm] = useState({ username: '', password: '' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const successMessage = location.state?.message || '';

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      await login(form.username, form.password);
      navigate('/finbric');
    } catch (err) {
      setError(err.response?.data?.message || 'Invalid username or password');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={styles.page}>
      <AuthHeader styles={styles} />
      <div className={styles.backgroundOrbOne} />
      <div className={styles.backgroundOrbTwo} />

      <main className={styles.content}>
        <div className={styles.shell}>
          <AuthHero />

          <section className={styles.card}>
            <span className={styles.cardEyebrow}>Welcome back</span>
            <h2 className={styles.title}>Sign in to Finbric</h2>
            <p className={styles.subtitle}>Access your community groups, loans, investments, and member balances.</p>

            {successMessage && <p className={styles.success}>{successMessage}</p>}
            {error && <p className={styles.error}>{error}</p>}

            <form onSubmit={handleSubmit} className={styles.form}>
              <div className={styles.field}>
                <label htmlFor="username">Username</label>
                <input
                  id="username"
                  name="username"
                  type="text"
                  value={form.username}
                  onChange={handleChange}
                  placeholder="Enter your username"
                  autoComplete="username"
                  required
                />
              </div>
              <div className={styles.field}>
                <label htmlFor="password">Password</label>
                <input
                  id="password"
                  name="password"
                  type="password"
                  value={form.password}
                  onChange={handleChange}
                  placeholder="Enter your password"
                  autoComplete="current-password"
                  required
                />
              </div>
              <button type="submit" className={styles.primaryButton} disabled={loading}>
                {loading ? 'Signing in...' : 'Sign in'}
              </button>
            </form>

            <p className={styles.link}>
              <Link to="/forgot-password">Forgot password?</Link>
            </p>
            <p className={styles.link}>
              New to Finbric? <Link to="/register">Create an account</Link>
            </p>
          </section>
        </div>
      </main>
    </div>
  );
}
